import { readFile, writeFile } from 'node:fs/promises';
const read = path => readFile(new URL('../' + path, import.meta.url), 'utf8');
const modules = await Promise.all(['policy.js', 'adapter.js', 'src/client.js'].map(read));
const body = modules.map(text => text.replace(/^import .*;\r?\n/gm, '').replace(/^export /gm, '')).join('\n');
await writeFile(new URL('../client.js', import.meta.url),
  '// Generated by npm run build. Edit src/client.js, policy.js or adapter.js.\n' +
  'window.__ModuleLoader__.load({ id: "dsh-preset-manager", factory(require) {\n' +
  'const React = require("react");\n' + body + '\nreturn { inject, apply };\n} });\n');
console.log('Built client.js (React is supplied by DSH)');
